import os
import sqlite3
from flask import Flask, jsonify, request

app = Flask(__name__)
DB = os.environ.get('RECIPE_DB', 'recipes.db')


def rows(query, params=()):
    with sqlite3.connect(DB) as conn:
        return conn.execute(query, params).fetchall()


@app.route('/recipes')
def list_recipes():
    term = request.args.get('q', '')
    found = rows('SELECT id, title FROM recipes WHERE title LIKE ?', ('%' + term + '%',))
    return jsonify(found)


@app.route('/recipes/<int:rid>')
def one(rid):
    row = rows('SELECT * FROM recipes WHERE id = ?', (rid,))
    return jsonify(row)


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000, debug=os.environ.get('DEBUG') == '1')

