import requests

URL = 'https://example.test/api/prices'


def fetch():
    reply = requests.get(URL, timeout=10)
    reply.raise_for_status()
    return reply.json()


try:
    print(fetch())
except requests.RequestException as err:
    print('could not fetch prices:', err)

